LEVEL = 1
CFG = {1: {"fails": 2}, 2: {"fails": 3}, 3: {"fails": 1}}
NEED_FAILS = CFG[LEVEL]["fails"]
tools = {"a": {"fails": 0, "up": True}, "b": {"fails": 0, "up": True}}
probe_results = {"a": ["ok", "fail", "fail", "fail"], "b": ["ok"] * 4}
for name, results in probe_results.items():
    for r in results:
        t = tools[name]
        t["fails"] = 0 if r == "ok" else t["fails"] + 1
        if t["fails"] >= NEED_FAILS:
            t["up"] = False
print({n: ("UP" if t["up"] else "DOWN") for n, t in tools.items()})

